changeSet.sql:

IF NOT EXISTS (select * from sys.foreign_keys where name = 'FK_CompanyDomainGroup_CompanyDomainSetting')
BEGIN
	alter table [dbo].[CompanyDomainGroup]  with check add constraint [FK_CompanyDomainGroup_CompanyDomainSetting] foreign key (CompanyID, DomainSettingID) references [dbo].[CompanyDomainSetting] (CompanyID, DomainSettingID) on delete cascade;
	alter table [dbo].[CompanyDomainGroup] check constraint [FK_CompanyDomainGroup_CompanyDomainSetting];
END

IF NOT EXISTS (select * from [sys].[default_constraints] where name = 'DF_CompanyDomainGroup_IsAdministrator')
BEGIN
	alter table [dbo].[CompanyDomainGroup] add constraint DF_CompanyDomainGroup_IsAdministrator default (0) for IsAdministrator;
END
